static uint16_t hmi_test_next_roll(void)
{
    static uint16_t roll = 0U;
    roll = (uint16_t)((roll + 1U) & 0xFFU);
    if ((roll == 0U) || (roll == 250U))
    {
        roll = (uint16_t)(roll + 1U);
        if (roll == 0U)
        {
            roll = 1U;
        }
    }
    return roll;
}

