/* 5.2 Reset / Timeout / Unavailable Behavior */

static void test_hmi_read_can_resets_status_fields_after_timeout(void)
{
    HMI_DATA_BLOCK_s *db;
    TIME_t local_time;
    CAN_CFG_CAN_DATA_s can;
    uint8_t crc_result;

    hmi_init();
    hmi_cfg();
    db = hmi_get();
    crc8_init();

    local_time.sec = 0U;
    local_time.up_time_ms = 0U;
    can.message_id = 0x61EU;
    can.data_length = 8U;
    can.frame_type = CAN_MSG_FRAME_STD;
    can.data[0] = 0x00U;
    can.data[1] = 50U;
    can.data[2] = 75U;
    can.data[3] = 50U;
    can.data[4] = 100U;
    can.data[5] = 0U;
    can.data[6] = hmi_test_next_roll();
    crc_result = 0U;
    crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = crc_result;
    hmi_read_can(local_time, db, &can);

    local_time.up_time_ms = 65537U;
    can.message_id = 0x999U;
    hmi_read_can(local_time, db, &can);

    TEST_ASSERT_TRUE(db->status.can_details.fault_can_time_out_flg);
    TEST_ASSERT_FALSE(db->status.charge_stop);
    TEST_ASSERT_EQUAL_UINT8(MAX_uint8_t, db->status.regen_level);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->status.charge_limit);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->status.v2l_soc);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->status.v2l_time);
    TEST_ASSERT_FALSE(db->status.v2l_enable);
    TEST_ASSERT_FALSE(db->status.avas_silent);
}

