static void test_hmi_read_can_distinguishes_unavailable_from_timeout(void)
{
    HMI_DATA_BLOCK_s *db;
    TIME_t local_time;
    CAN_CFG_CAN_DATA_s can;
    uint8_t crc_result;

    /* Scenario 1: never received -> unavailable, not timeout */
    hmi_init();
    hmi_cfg();
    db = hmi_get();
    local_time.sec = 0U;
    local_time.up_time_ms = 0U;
    can.message_id = 0x999U;
    can.data_length = 8U;
    can.frame_type = CAN_MSG_FRAME_STD;
    hmi_read_can(local_time, db, &can);
    TEST_ASSERT_TRUE(db->status.can_details.fault_can_unavailble_flg);

    /* Scenario 2: previously received then timed out -> timeout, not unavailable */
    hmi_init();
    hmi_cfg();
    crc8_init();
    can.message_id = 0x61EU;
    can.data[0] = 0x00U;
    can.data[1] = 50U;
    can.data[2] = 75U;
    can.data[3] = 50U;
    can.data[4] = 100U;
    can.data[5] = 0U;
    can.data[6] = hmi_test_next_roll();
    crc_result = 0U;
    crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = crc_result;
    hmi_read_can(local_time, db, &can);

    local_time.up_time_ms = 65537U;
    can.message_id = 0x999U;
    hmi_read_can(local_time, db, &can);

    TEST_ASSERT_TRUE(db->status.can_details.fault_can_time_out_flg);
    TEST_ASSERT_FALSE(db->status.can_details.fault_can_unavailble_flg);
}

