    can.message_id = 0x61EU;
    can.data_length = 8U;
    can.frame_type = CAN_MSG_FRAME_STD;

    /* prime pre_roll_counter with a throwaway frame so the frame(s)
       under test below are never mistaken for a duplicate, regardless
       of what a previous test left the static roll-counter state at */
    can.data[0] = 0x00U;
    can.data[1] = 0U;
    can.data[2] = 50U;
    can.data[3] = 50U;
    can.data[4] = 100U;
    can.data[5] = 0U;
    can.data[6] = 250U;
    crc_result = 0U;
    crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = crc_result;
    hmi_read_can(local_time, db, &can);

    can.data[0] = 0x00U;
    can.data[1] = 50U;
    can.data[2] = 75U;
    can.data[3] = 50U;
    can.data[4] = 100U;
    can.data[5] = 0U;
    can.data[6] = hmi_test_next_roll();
    crc_result = 0U;
    crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = crc_result;
    hmi_read_can(local_time, db, &can);

    can.data[0] = 0x00U;
