static void test_hmi_read_can_alternates_decode_and_timeout_branches_on_alternating_ids(void)
{
    HMI_DATA_BLOCK_s *db;
    TIME_t local_time;
    CAN_CFG_CAN_DATA_s can;
    uint8_t crc_result;

    hmi_init();
    hmi_cfg();
    db = hmi_get();
    crc8_init();

    local_time.sec = 0U;
    local_time.up_time_ms = 0U;
    can.data_length = 8U;
    can.frame_type = CAN_MSG_FRAME_STD;
    can.data[0] = 0x00U;
    can.data[2] = 75U;
    can.data[3] = 50U;
    can.data[4] = 100U;
    can.data[5] = 0U;

    /* call 1: matching id */
    can.message_id = 0x61EU;
    can.data[1] = 10U;
    can.data[6] = hmi_test_next_roll();
    crc_result = 0U;
    crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = crc_result;
    hmi_read_can(local_time, db, &can);
    TEST_ASSERT_EQUAL_UINT8(10U, db->status.regen_level);

    /* call 2: mismatching id, within timeout window */
    can.message_id = 0x999U;
    local_time.up_time_ms = 10U;
    hmi_read_can(local_time, db, &can);
    TEST_ASSERT_EQUAL_UINT8(10U, db->status.regen_level);
    TEST_ASSERT_FALSE(db->status.can_details.fault_can_unavailble_flg);

    /* call 3: matching id again, new value */
    can.message_id = 0x61EU;
    can.data[1] = 20U;
    can.data[6] = 2U;
    crc_result = 0U;
    crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = crc_result;
    local_time.up_time_ms = 20U;
    hmi_read_can(local_time, db, &can);
    TEST_ASSERT_EQUAL_UINT8(20U, db->status.regen_level);

    /* call 4: mismatching id again */
    can.message_id = 0x999U;
    local_time.up_time_ms = 30U;
    hmi_read_can(local_time, db, &can);
    TEST_ASSERT_EQUAL_UINT8(20U, db->status.regen_level);
}

